```
// @ts-nocheck
export default {
  meta: {
    type: "problem",
    docs: {
      description: "Enforce using @/env instead of process.env",
      category: "Best Practices",
      recommended: true,
    },
    fixable: undefined,
    schema: [
      {
        type: "object",
        properties: {
          excludeFiles: {
            type: "array",
            items: {
              type: "string",
            },
            description:
              "Array of file paths or patterns to exclude from this rule",
          },
        },
        additionalProperties: false,
      },
    ],
    messages: {
      useEnvImport:
        'Use import { env } from "@/env" instead of process.env for type safety',
    },
  },
  create(context) {
    const options = context.options[0] || {};
    const excludeFiles = options.excludeFiles || [];

    return {
      MemberExpression(node) {
        // Check if accessing process.env
        if (
          node.object.type === "Identifier" &&
          node.object.name === "process" &&
          node.property.type === "Identifier" &&
          node.property.name === "env"
        ) {
          // Get the current file path
          const filename = context.filename || context.getFilename();

          // Check if this file should be excluded
          const shouldExclude = excludeFiles.some((pattern) => {
            // Support both exact matches and pattern matching
            if (pattern.includes("*")) {
              // Simple glob pattern matching (e.g., "*.config.ts")
              const regex = new RegExp(
                "^" + pattern.replace(/\*/g, ".*").replace(/\./g, "\\.") + "$",
              );
              return regex.test(filename.split("/").pop());
            }
            // Check if filename ends with the pattern (for paths)
            return filename.endsWith(pattern);
          });

          if (shouldExclude) {
            return;
          }

          context.report({
            node,
            messageId: "useEnvImport",
          });
        }
      },
    };
  },
};
