// @ts-nocheck
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Cache the env schema to avoid re-parsing on every lint run
let envSchemaCache = null;

function parseEnvSchema() {
  if (envSchemaCache) {
    return envSchemaCache;
  }

  try {
    // Read the env.ts file
    const envPath = path.join(__dirname, "..", "src", "env.ts");
    const envContent = fs.readFileSync(envPath, "utf8");

    // Find the server and client blocks more accurately
    const serverVars = new Set();
    const clientVars = new Set();

    // Find server block - look for server: { and find matching }
    const serverStartIndex = envContent.indexOf("server: {");
    if (serverStartIndex !== -1) {
      let braceCount = 0;
      let inServerBlock = false;
      let serverBlockContent = "";

      for (let i = serverStartIndex; i < envContent.length; i++) {
        if (envContent[i] === "{") {
          braceCount++;
          inServerBlock = true;
        } else if (envContent[i] === "}") {
          braceCount--;
          if (braceCount === 0 && inServerBlock) {
            serverBlockContent = envContent.substring(serverStartIndex, i + 1);
            break;
          }
        }
      }

      // Extract variable names from server block - match any word followed by : and eventually z.
      const varMatches = serverBlockContent.matchAll(
        /^\s*(\w+):\s*z[\s\S]*?(?=^\s*\w+:|^\s*})/gm,
      );
      for (const match of varMatches) {
        serverVars.add(match[1]);
      }
    }

    // Find client block
    const clientStartIndex = envContent.indexOf("client: {");
    if (clientStartIndex !== -1) {
      let braceCount = 0;
      let inClientBlock = false;
      let clientBlockContent = "";

      for (let i = clientStartIndex; i < envContent.length; i++) {
        if (envContent[i] === "{") {
          braceCount++;
          inClientBlock = true;
        } else if (envContent[i] === "}") {
          braceCount--;
          if (braceCount === 0 && inClientBlock) {
            clientBlockContent = envContent.substring(clientStartIndex, i + 1);
            break;
          }
        }
      }

      // Extract variable names from client block
      const varMatches = clientBlockContent.matchAll(
        /^\s*(\w+):\s*z[\s\S]*?(?=^\s*\w+:|^\s*})/gm,
      );
      for (const match of varMatches) {
        clientVars.add(match[1]);
      }
    }

    envSchemaCache = { serverVars, clientVars };
    return envSchemaCache;
  } catch (error) {
    console.error("Failed to parse env.ts schema:", error);
    // Return empty sets if parsing fails
    return { serverVars: new Set(), clientVars: new Set() };
  }
}

export default {
  meta: {
    type: "problem",
    docs: {
      description:
        "Prevent accessing server-side environment variables in client components",
      category: "Best Practices",
      recommended: true,
    },
    fixable: undefined,
    schema: [],
    messages: {
      serverEnvInClient:
        'Cannot access server-side environment variable "{{envVar}}" in a client component. Use NEXT_PUBLIC_ prefixed variables or move this logic to a server component.',
    },
  },
  create(context) {
    let isClientComponent = false;
    let hasEnvImport = false;
    const { serverVars } = parseEnvSchema();

    return {
      Program(node) {
        // Check if the file starts with "use client"
        const sourceCode = context.getSourceCode();
        const firstToken = sourceCode.getFirstToken(node);
        if (firstToken && firstToken.type === "String") {
          isClientComponent = firstToken.value === "use client";
        }

        // Also check for 'use client' directive as a literal
        const firstStatement = node.body[0];
        if (
          firstStatement &&
          firstStatement.type === "ExpressionStatement" &&
          firstStatement.expression.type === "Literal" &&
          firstStatement.expression.value === "use client"
        ) {
          isClientComponent = true;
        }
      },

      ImportDeclaration(node) {
        // Check if importing env from @/env
        if (node.source.value === "@/env") {
          hasEnvImport = true;
        }
      },

      MemberExpression(node) {
        if (!isClientComponent || !hasEnvImport) {
          return;
        }

        // Check if accessing env.SOME_VAR
        if (
          node.object.type === "Identifier" &&
          node.object.name === "env" &&
          node.property.type === "Identifier"
        ) {
          const envVar = node.property.name;

          // Check if it's a server-side env var
          if (serverVars.has(envVar)) {
            context.report({
              node,
              messageId: "serverEnvInClient",
              data: {
                envVar,
              },
            });
          }
        }
      },
    };
  },
};
```

