// Rule to prevent accessing server-side environment variables in client components
// This rule checks for "use client" directive and prevents access to server env vars

program($body) where {
  $has_use_client = false(),
  $has_env_import = false(),

  // Check for "use client" directive
  $body <: contains `"use client"` => {
    $has_use_client = true()
  },

  // Check for env import from @/env
  $body <: contains `import { $imports } from "@/env"` => {
    $has_env_import = true()
  },

  // If both conditions are met, check for server env var access
  if ($has_use_client <: true(), $has_env_import <: true()) {
    $body <: contains `env.$VAR` as $env_access where {
      // List of known server-side variables (without NEXT_PUBLIC_ prefix)
      // These would need to be maintained based on your env.ts schema
      $VAR <: or {
        `DATABASE_URL`,
        `INNGEST_EVENT_KEY`,
        `INNGEST_SIGNING_KEY`,
        `OPENAI_API_KEY`,
        `ANTHROPIC_API_KEY`,
        `GROQ_API_KEY`,
        `AZURE_OPENAI_API_KEY`,
        `CARTESIA_API_KEY`,
        `GOOGLE_APPLICATION_CREDENTIALS`,
        `TELNYX_API_KEY`,
        `TWILIO_ACCOUNT_SID`,
        `TWILIO_AUTH_TOKEN`,
        `NYLAS_CLIENT_ID`,
        `NYLAS_CLIENT_SECRET`,
        `RESEND_API_KEY`,
        `LIVEKIT_API_KEY`,
        `LIVEKIT_API_SECRET`,
        `NEON_API_KEY`,
        `REDIS_URL`,
        `SENTRY_AUTH_TOKEN`
      },

      register_diagnostic(
        span=$env_access,
        message="Cannot access server-side environment variable \"$VAR\" in a client component. Use NEXT_PUBLIC_ prefixed variables or move this logic to a server component."
      )
    }
  }
}

